    '本頁保留的文件草稿已達上限。請先返回已有草稿的專案儲存，或匯出並丟棄，再編輯新的文件。',
  '文字超过草稿保留范围，本次输入未应用。': '文字超過草稿保留範圍，本次輸入未應用。',
  '丢弃这份保留在本页的未保存草稿？此操作不会取消已经提交的保存请求，也不会删除云端文档。':
    '丟棄這份保留在本頁的未儲存草稿？此操作不會取消已經提交的儲存請求，也不會刪除雲端文件。',
  '草稿已经变化，请重新核对后操作。': '草稿已經變化，請重新核對後操作。',
  '请先恢复或丢弃本页保留的草稿，再切换文档；可以先导出一份。':
    '請先恢復或丟棄本頁保留的草稿，再切換文件；可以先匯出一份。',
  '上次新建结果尚未确认。建议先导出草稿；切换会丢弃本页文字，但不会取消已经提交的保存请求。确定切换吗？':
    '上次新建結果尚未確認。建議先匯出草稿；切換會丟棄本頁文字，但不會取消已經提交的儲存請求。確定切換嗎？',
  '这份文档还有未保存的修改。放弃修改并切换吗？': '這份文件還有未儲存的修改。放棄修改並切換嗎？',
